export {escapeDisplay as escapeHTML} from './display-text.js';
import {escapeDisplay as escapeHTML} from './display-text.js';
const e=escapeHTML;
export const stageNames={'-1':'已结束',0:'待审核',1:'待见面',2:'待交接',3:'已完成'};
export const followupNames={pending:'待回访',confirmation:'待确认',attention:'需关注',completed:'已完成'};
export const workspaceFilters={application:'all',pet:'all',followup:'all',query:''};
export const recordFilters={q:'',status:'all',from:'',to:'',order:'desc',id:''};
export let knowledgeFilter='all';
export function setKnowledgeFilter(value){knowledgeFilter=value;}
export const petStatus=(p,apps)=>p.profile?.adopted||apps.some(a=>a.petId===p.id&&a.stage===3)?'adopted':apps.some(a=>a.petId===p.id&&a.stage>=0&&a.stage<3)?'process':p.published===false?'draft':'waiting';
export function avatar(name,url,cls=''){return url?`<img class="person-pet-avatar ${cls}" src="${e(url)}" alt="${e(name)}的头像">`:`<span class="person-pet-avatar initials ${cls}" aria-label="${e(name)}尚未上传头像">${e(String(name||'?').slice(0,1))}</span>`;}
export function pair(a,p){return `<span class="application-pair"><span>${avatar(a.name,a.snapshot?.avatarUrl)}<b>${e(a.name)}</b></span><i aria-hidden="true">→</i><span>${avatar(p?.name,p?.profile?.photoUrl,'pet-avatar')}<b>${e(p?.name||'宠物')}</b></span></span>`;}
const matches=(a,q)=>!q||a.toLowerCase().includes(q.trim().toLowerCase());
export const chips=(kind,items,value)=>`<div class="station-chips" role="group" aria-label="${e(kind)}筛选">${items.map(([id,label])=>`<button type="button" data-ws-filter="${kind}" data-value="${id}" aria-pressed="${value===id}" class="${value===id?'active':''}">${e(label)}</button>`).join('')}</div>`;
export const search=()=>`<form id="station-search" class="station-search"><label class="sr-only" for="station-query">搜索名字或内容</label><input id="station-query" name="query" value="${e(workspaceFilters.query)}" placeholder="搜索名字或内容" type="search"><button type="submit" class="button secondary">搜索</button></form>`;
export function applicationList(apps,pets,{home=false}={}){
 const f=workspaceFilters.application,q=workspaceFilters.query;
 const rows=apps.filter(a=>(f==='all'?(!home||a.stage>=0&&a.stage<3):String(a.stage)===f)&&matches(a.name+' '+pets.find(p=>p.id===a.petId)?.name+' '+a.note,q));
 return `${chips('application',[['all',home?'待处理':'全部'],...Object.entries(stageNames).sort((a,b)=>Number(a[0])-Number(b[0]))],f)}${search()}<p class="result-count">${rows.length} 份申请</p>${rows.map(a=>`<button class="online-pet application-item" data-live="application" data-id="${e(a.id)}">${pair(a,pets.find(p=>p.id===a.petId))}<span class="application-state"><small>${stageNames[a.stage]} · ${a.snapshot.verification==='verified'?'实名已核验':'实名待核验'}</small><span>›</span></span></button>`).join('')||'<div class="online-card"><p>没有符合条件的申请。</p></div>'}`;
}
export function petList(pets,apps){const names={all:'全部',waiting:'待领养',process:'领养流程中',adopted:'已领养',draft:'未公开'};const rows=pets.filter(p=>(workspaceFilters.pet==='all'||petStatus(p,apps)===workspaceFilters.pet)&&matches(p.name+' '+p.profile.description,workspaceFilters.query));return `${chips('pet',Object.entries(names),workspaceFilters.pet)}${search()}<p class="result-count">${rows.length} 位伙伴</p>${rows.map(p=>`<button class="online-pet" data-live="pet" data-id="${e(p.id)}">${avatar(p.name,p.profile.photoUrl,'pet-list-avatar')}<span><strong>${e(p.name)} <em class="status-pill ${petStatus(p,apps)}">${names[petStatus(p,apps)]}</em></strong><small>${e(p.profile.description||'还没有基础介绍')}</small></span><span>›</span></button>`).join('')||'<div class="online-card"><p>没有符合条件的伙伴。</p></div>'}`;}
export function summary(pets,apps,followups){const unscheduled=apps.filter(a=>a.stage===3&&!followups.some(f=>f.applicationId===a.id&&f.status!=='completed')).length;const counts=[['pets','all',pets.length,'位伙伴'],['applications','0',apps.filter(a=>a.stage===0).length,'待审核'],['followups','pending',followups.filter(f=>f.status==='pending').length+unscheduled,'待回访'],['followups','confirmation',followups.filter(f=>f.status==='confirmation').length,'待确认'],['followups','attention',followups.filter(f=>f.status==='attention').length,'需关注']];return `<div class="station-metrics">${counts.map(([page,filter,count,label])=>`<button data-live="metric" data-view="${page}" data-filter="${filter}"><strong>${count}</strong><small>${label}</small></button>`).join('')}</div>`;}
export function followupList(rows,apps,pets){const selected=workspaceFilters.followup;const unplanned=apps.filter(a=>a.stage===3&&!rows.some(r=>r.applicationId===a.id&&r.status!=='completed'));const list=rows.filter(f=>(selected==='all'||f.status===selected)&&matches(f.name+' '+pets.find(p=>p.id===f.petId)?.name+' '+f.history.map(h=>h.text).join(' '),workspaceFilters.query));return `${chips('followup',[['all','全部'],...Object.entries(followupNames)],selected)}${search()}${['all','pending'].includes(selected)&&unplanned.length?`<h2 class="spaced">安排下一次回访</h2>${unplanned.filter(a=>matches(a.name+' '+pets.find(p=>p.id===a.petId)?.name,workspaceFilters.query)).map(a=>`<button class="online-pet application-item" data-live="followup-new" data-id="${e(a.id)}">${pair(a,pets.find(p=>p.id===a.petId))}<small>已交接 · 点击安排回访</small></button>`).join('')}`:''}${list.map(f=>`<button class="online-pet application-item" data-live="followup" data-id="${e(f.id)}">${pair({name:f.name,snapshot:apps.find(a=>a.id===f.applicationId)?.snapshot},pets.find(p=>p.id===f.petId))}<span class="application-state"><span class="status-pill ${f.status}">${followupNames[f.status]}</span><small>${new Date(f.dueAt).toLocaleDateString('zh-CN')}${f.status!=='completed'&&Date.parse(f.dueAt)<Date.now()?' · 已到期':''}</small></span><small>${e(f.history.at(-1)?.text||'等待跟进')}</small></button>`).join('')}${!list.length&&!unplanned.length?'<div class="online-card"><h2>暂时没有回访事项</h2><p>领养交接完成后，在这里安排到家回访并记录后续情况。</p></div>':''}`;}
export function contactCard(a,p){const s=a.snapshot;return `<section class="online-card">${pair(a,p)}<p class="status-pill">${stageNames[a.stage]} · ${s.verification==='verified'?'实名已核验':'实名待核验'}</p><dl class="contact-details"><div><dt>姓名</dt><dd>${e(s.realName||'未提供')}</dd></div><div><dt>电话</dt><dd>${s.phone?`<a href="tel:${e(s.phone.replace(/[^\d+]/g,''))}">${e(s.phone)}</a>`:'未提供'}</dd></div><div><dt>微信</dt><dd>${e(s.wechat||'未提供')}${s.wechat?`<button data-live="copy-wechat" data-id="${e(a.id)}" class="text-button">复制</button>`:''}</dd></div>${s.email?`<div><dt>邮箱</dt><dd>${e(s.email)}</dd></div>`:''}</dl><button class="button secondary full" data-live="applicant" data-id="${e(a.id)}">查看领养者主页 →</button><small class="online-note">申请人确认分享给本站的联系方式</small></section>`;}
export function applicantPage(a,apps,pets){const same=apps.filter(x=>(a.adopterId&&x.adopterId===a.adopterId)||x.id===a.id),adopted=same.filter(x=>x.stage===3),l=a.snapshot.lifestyle;return `<section class="online-card applicant-hero">${avatar(a.name,a.snapshot.avatarUrl)}<h1>${e(a.name)}</h1><p>${e(l?.analysis?.title||'认真认识每一位伙伴')}</p><small>以下是申请人确认分享给本站的资料</small></section><section class="online-card"><h2>已领养的伙伴</h2>${adopted.length?adopted.map(x=>{const p=pets.find(p=>p.id===x.petId);return `<button class="online-pet" data-live="pet" data-id="${e(x.petId)}">${avatar(p?.name,p?.profile?.photoUrl)}<span>${e(p?.name||'宠物')}<small>在本站完成领养</small></span></button>`;}).join(''):'<p>目前没有在本站完成的领养记录。</p>'}</section><section class="online-card"><h2>生活画像</h2><p>${e(l?.analysis?.summary||'尚未分享')}</p>${(l?.analysis?.highlights||[]).map(h=>`<span class="status-pill">${e(h)}</span>`).join('')}<details><summary>查看已分享的访谈回答</summary>${Object.values(l?.answers||{}).map(v=>`<p>${e(v.text)}</p>`).join('')}</details></section>`;}
